extracted_python_code:
result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= "2023-01-01")
).PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

recent_buy_transactions = Transactions.WHERE(
    (LOWER(transaction_type) == 'buy') & (DATEDIFF("days", date_time, DATETIME('now')) <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
)

result = recent_buy_transactions.PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

customer_metrics = Broker.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_period) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS('-', YEAR(join_date), LPAD(MONTH(join_date), 2, '0'))
).PARTITION(
    name='monthly_groups', by=signup_month
).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

distinct_customer_ids = Transactions.WHERE(LOWER(transaction_type) == 'buy').PARTITION(name="distinct_customers", by=customer_id).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="unique_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

transactions_in_last_30_days = Transactions.WHERE(
    DATEDIFF("days", date_time, DATETIME('now')) <= 30
).CALCULATE(
    customer_country=customer.country
)

top_countries_by_amount = transactions_in_last_30_days.PARTITION(
    name="countries", 
    by=(customer_country)
).CALCULATE(
    country=customer_country,
    num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(
    5, 
    by=total_transaction_amount.DESC()
)

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & 
            (DATEDIFF("days", date, DATETIME('now')) <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME("now")) <= 70
        ).transactions_made
    )
)

sales_by_model_with_m5_vin = Dealership.Cars.WHERE(
    LIKE(LOWER(vin_number), '%m5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

asp_q1_2023 = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 6))
)

distinct_customer_ids = Sales.PARTITION(name="customer_groups", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

cash_salesperson_ids = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

shortest_employment_salesperson = Salespersons.WHERE(
    PRESENT(termination_date)
).CALCULATE(
    salesperson_name=JOIN_STRINGS(" ", first_name, last_name),
    phone_number=phone,
    days_employed=DATEDIFF("days", hire_date, termination_date)
).TOP_K(
    1, 
    by=days_employed.ASC()
)

weekend_payments_to_utility_co = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

inventory_cars = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
).WHERE(
    RANKING(by=snapshot_date.DESC(), allow_ties=True) == 1
).WHERE(
    is_in_inventory == True
).car.CALCULATE(
    _id,
    make,
    model,
    year
)

result = DermTreatment.Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            (ENDSWITH(LOWER(email), '@gmail.com')) | (ENDSWITH(LOWER(email), '@yahoo.com'))
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (LOWER(diagnosis.diag_name) == LOWER('Psoriasis vulgaris')) &
                    (LOWER(drug.drug_type) == LOWER('Biologic'))
                )
            ) == 1
        )
    )
)

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(
            LOWER(first_name) == LOWER("Alice")
        ).treatments_received.WHERE(
            (start_dt >= DATETIME("now", "start of month", "-6 months")) &
            (start_dt < DATETIME("now", "start of month"))
        )
    )
)

avg_weight_drugalin = DermTreatment.Drugs.WHERE(LOWER(drug_name) == 'drugalin').CALCULATE(
    average_weight=AVG(treatments_used_in.patient.weight_kg)
)

caw_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(LOWER(gender) == 'male').weight_kg)
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

distinct_doctor_states = DermTreatment.Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

top_insurance_types_by_pasi = DermTreatment.Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=(insurance_type)
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score_100=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(5, by=avg_pasi_score_100.ASC())

top_diagnoses = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diag_name=diag_name,
    num_patients=NDISTINCT(treatments_for.patient.patient_id),
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas)
).TOP_K(
    3,
    by=(max_itch_score.DESC(), num_patients.DESC())
)

recent_psoriasis_treatments = DermTreatment.CALCULATE(
    treatment_count=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (PRESENT(drug.fda_appr_dt)) &
            (PRESENT(end_dt)) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6)
        )
    )
)

avg_age_of_patients = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    )
)

result = Merchants.CALCULATE(
    merchant_name=name,
    cpur=NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).WHERE(
            PRESENT(coupon_id)
        ).coupon_id
    ) / NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).txid
    )
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

tuc_in_past_month = Ewallet.CALCULATE(
    tuc=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

distinct_receiving_merchants = Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

top_5_countries_by_sent_amount = Ewallet.Transactions.WHERE(
    sender_type == 0
).CALCULATE(
    sender_country=sending_user.country,
    tx_amount=amount,
    sender_uid=sending_user.uid
).PARTITION(
    name="countries", by=(sender_country)
).CALCULATE(
    country=sender_country,
    total_transaction_amount=SUM(Transactions.tx_amount),
    num_distinct_users=NDISTINCT(Transactions.sender_uid)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (LOWER(status) == 'active') & 
            (CONTAINS(LOWER(category), 'retail'))
        ).balances.WHERE(
            updated_at >= DATETIME('now', 'start of day')
        ).balance
    )
)

# Find the earliest snapshot date in 2023
earliest_2023_snapshot = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).TOP_K(1, by=snapshot_date.ASC())

# Calculate the average limits for that earliest date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_monthly
    )
)

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", user.created_at, created_at) <= 365
        )
    ) == 1
).CALCULATE(
    user_name=username,
    user_email=email,
    signup_date=created_at
)
